"""Download Coval simulation audio recordings for local benchmark artifacts."""

from __future__ import annotations

from pathlib import Path
from typing import Optional, Tuple
from urllib.parse import urlparse

from rasa.builder.copilot.mcp_server.tools.coval.client import CovalClient

_CONTENT_TYPE_EXTENSIONS = {
    "audio/wav": ".wav",
    "audio/x-wav": ".wav",
    "audio/wave": ".wav",
    "audio/mpeg": ".mp3",
    "audio/mp3": ".mp3",
    "audio/mp4": ".m4a",
    "audio/aac": ".aac",
    "audio/ogg": ".ogg",
    "audio/webm": ".webm",
}


def audio_extension_from_url_or_content_type(
    url: str,
    content_type: Optional[str] = None,
) -> str:
    """Pick a file extension from the download URL path or Content-Type.

    Preserves Coval's format (no re-encoding). Defaults to ``.wav`` when unknown.
    """
    path = urlparse(url).path
    suffix = Path(path).suffix.lower()
    if suffix and suffix.startswith(".") and len(suffix) <= 5:
        return suffix

    if content_type:
        media_type = content_type.split(";", 1)[0].strip().lower()
        if media_type in _CONTENT_TYPE_EXTENSIONS:
            return _CONTENT_TYPE_EXTENSIONS[media_type]
    return ".wav"


async def download_simulation_audio(
    client: CovalClient,
    simulation_id: str,
    *,
    timeout_s: float = 120.0,
) -> Tuple[bytes, str]:
    """Download a simulation recording and return ``(bytes, extension)``.

    ``extension`` includes the leading dot (e.g. ``.wav``) and matches whatever
    Coval served — bytes are not re-encoded.
    """
    payload = await client.get_simulation_audio_url(simulation_id)
    audio_url = str(payload.get("audio_url") or payload.get("url") or "")
    body, content_type = await client.download_url_bytes(
        audio_url,
        timeout_s=timeout_s,
    )
    if not body:
        raise ValueError(
            f"Coval audio download for {simulation_id} returned empty body"
        )
    extension = audio_extension_from_url_or_content_type(audio_url, content_type)
    return body, extension
